package com.collegewise.exception;
import org.springframework.dao.DataIntegrityViolationException;
import java.util.*; import jakarta.validation.ConstraintViolationException;import org.springframework.http.*; import org.springframework.security.core.AuthenticationException;import org.springframework.web.bind.MethodArgumentNotValidException; import org.springframework.web.bind.annotation.*; import org.springframework.web.server.ResponseStatusException;import org.springframework.http.converter.HttpMessageNotReadableException;import org.springframework.web.method.annotation.MethodArgumentTypeMismatchException;
@RestControllerAdvice public class GlobalExceptionHandler { @ExceptionHandler(MethodArgumentNotValidException.class) ResponseEntity<?> invalid(MethodArgumentNotValidException e){Map<String,String> errors=new LinkedHashMap<>();e.getBindingResult().getFieldErrors().forEach(x->errors.put(x.getField(),x.getDefaultMessage()));return ResponseEntity.badRequest().body(Map.of("error","Validation failed","fields",errors));} @ExceptionHandler({HttpMessageNotReadableException.class,MethodArgumentTypeMismatchException.class,NumberFormatException.class,ConstraintViolationException.class}) ResponseEntity<?> invalidRequest(Exception e){return ResponseEntity.badRequest().body(Map.of("error","Invalid request value"));} @ExceptionHandler(ResponseStatusException.class) ResponseEntity<?> status(ResponseStatusException e){return ResponseEntity.status(e.getStatusCode()).body(Map.of("error",e.getReason()==null?"Request failed":e.getReason()));} @ExceptionHandler(AuthenticationException.class) ResponseEntity<?> auth(AuthenticationException e){return ResponseEntity.status(HttpStatus.UNAUTHORIZED).body(Map.of("error","Invalid email or password"));} @ExceptionHandler(DataIntegrityViolationException.class) ResponseEntity<?> conflict(DataIntegrityViolationException e){return ResponseEntity.status(HttpStatus.CONFLICT).body(Map.of("error","The request conflicts with an existing record"));} @ExceptionHandler(Exception.class) ResponseEntity<?> unknown(Exception e){return ResponseEntity.status(HttpStatus.INTERNAL_SERVER_ERROR).body(Map.of("error","An unexpected error occurred"));} }
